     "summary": "上证报中国证券网讯（记者 陈梦娜）记者10月9日从东航获悉，2026年中秋至国庆长假期间，东航投入837架客机服务旅客节假日出行。9月25日至10月7日，东航累计执行航班超3.9万班次，日均3120班，共服务旅客580万余人次。10月7日，长假出行迎来返程高峰。为了满足旅客出行需求，东航特别以增班、机型“小换大”等方式，在多条重点航线增投运力，保障旅客顺畅返程。",
